import{_ as e,c as a,a2 as p,o}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"第一百四十三章 我也经历过苦难","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/143第一百四十三章 我也经历过苦难.md","filePath":"meditation/巴利文大藏经/143第一百四十三章 我也经历过苦难.md"}'),_={name:"meditation/巴利文大藏经/143第一百四十三章 我也经历过苦难.md"};function r(n,t,i,s,d,c){return o(),a("div",null,t[0]||(t[0]=[p('<h1 id="第一百四十三章-我也经历过苦难" tabindex="-1">第一百四十三章 我也经历过苦难 <a class="header-anchor" href="#第一百四十三章-我也经历过苦难" aria-label="Permalink to &quot;第一百四十三章 我也经历过苦难&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>2.第二品</p><p>相应部15相应11经/不幸者经(无始相应/因缘篇/如来记说)</p><p>有个时候，佛陀住在舍卫城的祇树林给孤独园，有一天，佛陀对出家弟子们说：“弟子们，生死轮回是永无止境的，是无穷无尽的，不明白世间的真相、规则，被无知障碍，被贪爱束缚捆绑的众生，他们的生死轮回是循环不止的，他们无法知道自己生死轮回的起点在什么地方。</p><p>弟子们，如果你们看见别人，看见众生不幸、苦难、痛苦、烦恼、忧愁、悲伤、苦闷、忧虑、绝望、生病、衰老、死亡的时候，就要告诉自己：「在过去无穷无尽、循环不止的生死轮回中，我也经历过他们这些不幸、苦难、痛苦、烦恼、忧愁、悲伤、苦闷、忧虑、绝望、生病、衰老、死亡。」</p><p>这是为什么呢？弟子们，因为生死轮回是永无止境的，是无穷无尽的！所以你们经历的不幸、苦难、痛苦、烦恼、忧愁、悲伤、苦闷、忧虑、绝望、生病、衰老、死亡也是永无止境、无穷无尽的。这些不明白世间的真相、规则，被无知障碍，被贪爱束缚捆绑的众生，他们的生死轮回也是循环不止的，也是无穷无尽的，他们也是无法知道他们自己生死轮回的起点在什么地方的。</p><p>弟子们，你们无数次的生死轮回，无数次的承受痛苦，无数次的经历不幸，无数次的忧愁、悲伤、苦闷、忧虑、绝望。无数次的死后埋入墓地。弟子们，你们要从世间解脱出来，要从生死轮回中解脱出来，就不要再挂念和执着世间一切的事物，就不要再执着和挂念自己一切的行为、言语、念想。这样你们就不会被世间一切的事物束缚捆绑，这样你们就不会被自己的行为、言语、念想束缚捆绑。这样你们就能最终从生死轮回中永远的解脱出来。”</p><p>佛陀说法后，听法的出家弟子们都再次的顶礼佛陀，随喜赞叹佛陀说法的无量功德，他们都按着佛陀所说的法去修行。</p>',9)]))}const f=e(_,[["render",r]]);export{m as __pageData,f as default};
